CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,username VARCHAR(40) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,role VARCHAR(16) NOT NULL DEFAULT 'USER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE learning_records(id CHAR(36) PRIMARY KEY,user_id BIGINT NOT NULL,topic VARCHAR(40) NOT NULL,title VARCHAR(150) NOT NULL,kind VARCHAR(20) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'OPEN',snapshot JSON NOT NULL,note TEXT,version INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_record_user(user_id,updated_at));
CREATE TABLE submissions(id CHAR(36) PRIMARY KEY,user_id BIGINT NOT NULL,topic VARCHAR(40) NOT NULL,language VARCHAR(16) NOT NULL,source MEDIUMTEXT NOT NULL,result JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_submission_user(user_id,created_at));
CREATE TABLE experiments(id VARCHAR(40) PRIMARY KEY,title VARCHAR(100) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,version INT NOT NULL DEFAULT 0);
INSERT INTO experiments(id,title) VALUES('reverse','反转链表'),('binary','二分查找'),('reference','对象与引用');
